import logging
import pathlib
from abc import ABCMeta, abstractmethod
from collections.abc import Generator
from contextlib import contextmanager
from datetime import datetime
from functools import cached_property, wraps
from time import sleep, time
from typing import Optional, Union

import attr
from taf.config.testline import PduPort  # type: ignore[import-untyped]
from taf.config.testline.enb import RealEnb  # type: ignore[import-untyped]
from taf.config.testline.ue import CUS as CusTaf  # type: ignore[import-untyped]
from taf.config.testline.ue import IPHY as IphyTaf
from taf.transport.ssh import ConnectFailedError, ProxySSHConnection, SSHConnection  # type: ignore[import-untyped]
from ute_testline_configuration.ute_config import CUS as CusUte  # type: ignore[import-untyped]
from ute_testline_configuration.ute_config import IPHY as IphyUte
from ute_testline_configuration.ute_config import FSMr3, FSMr4

from taf.ul.ue.sim.env_setup.devices.pdu import TAFPDU
from taf.ul.ue.sim.env_setup.logger import MAIN_LOGGER_FORMAT
from taf.ul.ue.sim.env_setup.settings import NMAP_LOGGER, PACKAGE_NAME, RECOVERY_LOG_NAME
from taf.ul.ue.sim.env_setup.utils.exceptions import HostAvailable, HostSSHUnavailable, HostUnavailable
from taf.ul.ue.sim.env_setup.utils.ssh_utils import get_ssh
from taf.ul.ue.sim.env_setup.utils.tools import get_time_diff, is_host_available


def log_error(fun):
    @wraps(fun)
    def inner(*args, **kwargs):
        self = args[0]
        try:
            self.logger.debug(f"Executing {fun.__name__} with {args}, {kwargs}")
            ret = fun(*args, **kwargs)
            self.logger.debug(f"Executing {fun.__name__} with {args}, {kwargs} done")
            return ret
        except Exception as err:
            self.logger.debug(f"Error upon executing {fun.__name__} occurred. {err}")
            raise

    return inner


@attr.s(cmp=False, hash=True)
class Device(metaclass=ABCMeta):
    idx = attr.ib(type=int)
    configuration = attr.ib(type=Union[RealEnb, FSMr4, FSMr3, IphyTaf, IphyUte, CusTaf, CusUte])
    output_directory_path = attr.ib(type=Union[str, pathlib.Path])
    config_type = attr.ib(type="str")
    name = attr.ib(type=str)
    remote_host = attr.ib(default="", type=str, init=False)
    _pdu = attr.ib(default=None, type=Optional[TAFPDU], init=False, hash=False)
    _lmp_ip = attr.ib(default="", type=str, init=False, hash=False)

    @property
    def lmp_ip(self) -> str:
        """Returns LMP IP address for the device"""
        if not self._lmp_ip:
            if self.config_type == "ute":
                self._lmp_ip = self._get_lmp_ip_for_ute()
            if self.config_type == "taf":
                self._lmp_ip = self._get_lmp_ip_for_taf()
        return self._lmp_ip

    @lmp_ip.setter
    def lmp_ip(self, value):
        self.logger.debug(f"lmp_ip setter:  {self._lmp_ip} -> {value}")
        self._lmp_ip = value

    def _reset_lmp_ip(self):
        self._lmp_ip = ""
        self.logger.debug("Reset of lmp_ip done.")

    @property
    def password(self) -> str:
        """Returns password for the device"""
        return self._get_lmp_password()

    @abstractmethod
    def _get_lmp_ip_for_taf(self) -> str:
        """Returns LMP IP if UTE schema was used as a config in __init__.py for TL"""

    @abstractmethod
    def _get_lmp_ip_for_ute(self) -> str:
        """Returns LMP IP if TAF schema was used as a config in __init__.py for TL"""

    @abstractmethod
    def _get_lmp_password(self) -> str:
        """Returns password for the device"""

    @cached_property
    def logger(self) -> logging.Logger:
        return logging.getLogger(f"{PACKAGE_NAME}.{self.remote_host}.{self.name}")

    @cached_property
    def logger_recovery(self) -> logging.Logger:
        return logging.getLogger(f"{RECOVERY_LOG_NAME}.{self.remote_host}.{self.name}")

    @cached_property
    def logger_nmap(self) -> logging.Logger:
        return logging.getLogger(f"{NMAP_LOGGER}.{self.remote_host}.{self.name}")

    @cached_property
    def pdu(self) -> TAFPDU:
        try:
            pdu = self._create_pdu_with_ute_config()
        except AttributeError:
            pdu_config = self._get_taf_pdu_config()
            pdu = self._create_pdu_with_taf_config(pdu_config)
        self.logger.debug(pdu)
        return pdu

    @abstractmethod
    def _get_taf_pdu_config(self):
        pass

    @staticmethod
    def _create_pdu_with_taf_config(pdu_port: PduPort) -> TAFPDU:
        return TAFPDU(pdu_port.port_no, pdu_port.pdu)

    def _create_pdu_with_ute_config(self) -> TAFPDU:
        pdu_conf = self.configuration.pdu
        try:
            pdu = TAFPDU(
                pdu_conf.port,
                device_name=pdu_conf.device,
                address=pdu_conf.addr,
                protocol=pdu_conf.protocol,
            )
        except (AttributeError, KeyError):
            pdu = TAFPDU(pdu_conf.port, device_name=pdu_conf.device, address=pdu_conf.addr)
        return pdu

    def __str__(self) -> str:
        return str(self.__dict__)

    def reset(self) -> None:
        """
        Reset the device by resetting the PDU outlet.
        If the PDU outlet is already off, it will not change it.
        Method will be triggered with 5 retires if any connection to unit fails.
        """
        for attempt in range(1, 6):
            try:
                self.logger.debug("Attempt {} to reset PDU Device.".format(attempt))
                self._reset()
                return
            except Exception as err:
                self.logger.error("Resetting PDU Device failed with error: {}. Retrying...".format(err))
                sleep(10 * attempt)
        raise OSError("Could not reset the device after 5 attempts. Check PDU connection.")

    def _reset(self) -> None:
        alias = f"get_pdu_status_{self.name}_{self.pdu.address}_{self.pdu.port}__{self.lmp_ip}"
        if self.pdu.get_pdu_status(alias, self.logger) == "off":
            self.logger.debug("PDU outlet off, not going to change it.")
            return
        self.logger.debug(
            "Going to reboot {}: PDU name = {}, PDU addr = {}, PDU outlet = {}".format(
                self.name, self.pdu.device_name, self.pdu.address, self.pdu.port
            )
        )
        alias = f"reboot_{self.name}_{self.pdu.address}_{self.pdu.port}"
        self.pdu.reset_port_with_verification(alias, self.logger)

    @log_error
    def wait_for_interfaces_and_ssh(
        self,
        ping_timeout: int = 300,
        ssh_timeout: int = 300,
        skip_unavailable: bool = False,
        ssh_connection: Optional[SSHConnection] = None,
    ) -> None:
        start_time = time()
        if self.pdu.get_pdu_status(self._create_alias("get_pdu_status"), self.logger) == "off":
            self.logger.debug(
                "PDU [{}::{}] outlet off [{}_{}], not going to change it. Skipping wait for ping/ssh".format(
                    self.pdu.address,
                    self.pdu.port,
                    self.remote_host,
                    self.lmp_ip,
                )
            )
            return

        if ssh_connection is not None:
            self._wait_for_interfaces_and_ssh(ssh_connection, start_time, ping_timeout, ssh_timeout, skip_unavailable)
        else:
            with self._get_remote_host_ssh() as ssh_connection:
                self.logger.debug("Using remote host alias: to wait for interfaces and ssh.")
                self._wait_for_interfaces_and_ssh(ssh_connection, start_time, ping_timeout, ssh_timeout, skip_unavailable)

    def _wait_for_interfaces_and_ssh(
        self, ssh_connection: SSHConnection, start_time: float, ping_timeout: int, ssh_timeout: int, skip_unavailable: bool
    ) -> None:
        if skip_unavailable:
            sleep(2)
            self.logger.debug(f"PING NOK SKIP - 'skip_unavailable' = {skip_unavailable}.")
        else:
            self._wait_until_host_is_unavailable(ssh_connection, timeout=60)
        self._wait_until_host_is_available(ssh_connection, get_time_diff(start_time, ping_timeout - 60))
        self._wait_for_host_ssh(ssh_connection, get_time_diff(start_time, ping_timeout + ssh_timeout))

    def _wait_until_host_is_available(self, ssh_connection: SSHConnection, timeout: float = 180) -> None:
        self.logger.debug(f"PING OK START: {self.name} {self.lmp_ip}")
        start_time = time()
        while time() - start_time < timeout:
            if is_host_available(
                connection=ssh_connection,
                host=self.lmp_ip,
                logger=self.logger_nmap,
            ):
                self.logger.debug(f"PING OK DONE: {self.name} {self.lmp_ip}")
                return
        raise HostUnavailable(self.lmp_ip, self.remote_host)

    def _wait_until_host_is_unavailable(self, ssh_connection: SSHConnection, timeout: int) -> None:
        self.logger.debug(f"PING NOK START: {self.name} {self.lmp_ip}")
        start_time = time()
        while time() - start_time < timeout:
            if not is_host_available(
                connection=ssh_connection,
                host=self.lmp_ip,
                logger=self.logger_nmap,
            ):
                self.logger.debug(f"PING NOK DONE: {self.name} {self.lmp_ip}")
                return
        raise HostAvailable(self.lmp_ip, self.remote_host)

    def _wait_for_host_ssh(self, ssh_connection: SSHConnection, timeout: float = 180) -> None:
        self.logger.debug(f"SSH OK START: {self.name} {self.lmp_ip}")
        start_time = time()

        def _configure_taf_transport_ssh_logger():
            taf_ssh_logger = logging.getLogger("taf.transport.ssh")
            if taf_ssh_logger.handlers:
                return
            taf_ssh_logger.setLevel(logging.DEBUG)
            fh = logging.FileHandler(pathlib.Path(self.output_directory_path) / "taf.transport.ssh.log")
            fh.setLevel(logging.DEBUG)
            formatter = logging.Formatter(MAIN_LOGGER_FORMAT)
            fh.setFormatter(formatter)
            taf_ssh_logger.addHandler(fh)

        _configure_taf_transport_ssh_logger()
        while time() - start_time < timeout:
            try:
                with self._get_device_ssh(ssh_connection):
                    self.logger.debug(f"SSH OK DONE: {self.name} {self.lmp_ip}")
                    return
            except ConnectFailedError:
                pass
            except Exception as err:
                self.logger.debug(f"SSH OK FAIL: {self.name} {self.lmp_ip} :: {type(err)}:{err}")
                raise
        raise HostSSHUnavailable(self.lmp_ip, self.remote_host)

    def __wait_for_constant_pingable(self, ssh: SSHConnection, skip_reset: bool, first_timeout: int):
        try:
            self._wait_until_host_is_unavailable(ssh, timeout=first_timeout)
            if not skip_reset:
                self.reset()
            self._wait_until_host_is_available(ssh)
            self._wait_until_host_is_unavailable(ssh, timeout=90)
            self._wait_until_host_is_available(ssh)
            self._wait_until_host_is_unavailable(ssh, timeout=90)
        except HostAvailable:
            return
        raise OSError(f"Rolling reboot on device\n{self}")

    def _wait_until_constant_pingable(self, skip_reset=False, first_timeout=90, ssh_connection: Optional[SSHConnection] = None):
        """
        This function waits for device to be constantly pingable for at least 90s.
        If ping will fail then reset is performed and wait for device to be pingable again.
        Next we wait 90s to check if it's stable. For FSMr3 it might stop being pingable for a few seconds, therefore
        we need to wait until it becomes pingable again and then wait 90s again.
        If device fails to respond 90 times, IOError is raised.
        """

        if ssh_connection is None:
            with self._get_remote_host_ssh() as ssh_connection:
                self.__wait_for_constant_pingable(ssh_connection, skip_reset, first_timeout)
        else:
            self.logger.debug("Using provided ssh to wait for constant pingable.")
            self.__wait_for_constant_pingable(ssh_connection, skip_reset, first_timeout)

    def _create_alias(self, start_str: str) -> str:
        return f"{start_str}_{datetime.now()}_{self.lmp_ip}"

    @contextmanager
    def _get_remote_host_ssh(self) -> Generator[SSHConnection, None, None]:
        with get_ssh(self.remote_host, "ute", "ute", 10, logger=self.logger) as ssh_conn:
            yield ssh_conn

    @contextmanager
    def _get_device_ssh(self, proxy: SSHConnection) -> Generator[ProxySSHConnection, None, None]:
        with get_ssh(self.lmp_ip, "toor4nsn", self.password, 10, proxy=proxy, logger=self.logger) as ssh_conn:
            yield ssh_conn
